}

void rsconfRegisterReadiness(void) {
    pthread_once(&onceModulesReadyCond, initModulesReadyCond);
    if (!rsconfShouldDelayReadyNotify(runConf)) return;

    pthread_mutex_lock(&mutModulesReady);
    if (bModulesReadyNotifySent) {
